(* [comment removed for export] *)
Lemma rchain_frame_sp (M M' : word -> option byte) lo fp RC :
  rchain M lo fp RC -> 16 <= lo -> lo mod 8 = 0 -> fp <> lo + 8 -> ar_stack_top ar < 2 ^ 64 ->
  (forall x : word, lo <= bv_unsigned x < ar_stack_top ar -> M' x = M x) ->
